package com.example.qahwamanager.ui.loyalty

import android.content.Context
import android.print.PrintAttributes
import android.print.PrintManager
import android.webkit.WebView
import android.webkit.WebViewClient

/**
 * Generates and prints an A4 sheet of Table QR Code Stickers using Android's native [PrintManager].
 * Works 100% offline using vector SVG QR codes generated by [QrCodeGenerator].
 */
object TableQrPrintHelper {

    fun printTableQrSheet(
        context: Context,
        cafeName: String,
        baseStandUrl: String,
        tableCount: Int,
        stampsRequired: Int,
        rewardTitle: String,
    ) {
        val safeCount = tableCount.coerceIn(1, 40)
        val html = buildPrintableHtml(
            cafeName = cafeName.ifBlank { "Qahwa Café" },
            baseStandUrl = baseStandUrl,
            tableCount = safeCount,
            stampsRequired = stampsRequired,
            rewardTitle = rewardTitle,
        )

        val webView = WebView(context)
        webView.webViewClient = object : WebViewClient() {
            override fun onPageFinished(view: WebView, url: String?) {
                val printManager = context.getSystemService(Context.PRINT_SERVICE) as? PrintManager ?: return
                val jobName = "Qahwa_Table_QR_Stickers"
                val adapter = view.createPrintDocumentAdapter(jobName)
                val attrs = PrintAttributes.Builder()
                    .setMediaSize(PrintAttributes.MediaSize.ISO_A4)
                    .setColorMode(PrintAttributes.COLOR_MODE_COLOR)
                    .build()
                printManager.print(jobName, adapter, attrs)
            }
        }
        webView.loadDataWithBaseURL(null, html, "text/html", "UTF-8", null)
    }

    fun buildPrintableHtml(
        cafeName: String,
        baseStandUrl: String,
        tableCount: Int,
        stampsRequired: Int,
        rewardTitle: String,
    ): String {
        val cleanCafe = escapeHtml(cafeName)
        val cleanReward = escapeHtml(rewardTitle)
        val cardsHtml = StringBuilder()

        for (tableNo in 1..tableCount) {
            val separator = if (baseStandUrl.contains("?")) "&" else "?"
            val tableUrl = "${baseStandUrl}${separator}table=$tableNo"
            val svg = QrCodeGenerator.toSvg(tableUrl)
            cardsHtml.append(
                """
                <div class="sticker">
                    <div class="badge">TABLE $tableNo · طاولة $tableNo</div>
                    <div class="cafe-title">$cleanCafe</div>
                    <div class="qr-box">$svg</div>
                    <div class="reward-pill">☕ $stampsRequired = $cleanReward</div>
                    <div class="cta-fr">Scannez pour cumuler vos points fidélité</div>
                    <div class="cta-ar" dir="rtl">امسح الرمز لجمع النقاط وربح مشروب مجاني</div>
                </div>
                """.trimIndent()
            )
        }

        return """
            <!DOCTYPE html>
            <html lang="fr">
            <head>
                <meta charset="UTF-8"/>
                <title>$cleanCafe — Table QR Stickers</title>
                <style>
                    @page { size: A4; margin: 10mm; }
                    * { box-sizing: border-box; margin: 0; padding: 0; }
                    body {
                        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                        background: #FFFFFF;
                        color: #143023;
                    }
                    .grid {
                        display: grid;
                        grid-template-columns: repeat(3, 1fr);
                        gap: 8mm;
                    }
                    .sticker {
                        border: 2px solid #143023;
                        border-radius: 14px;
                        padding: 10px 8px;
                        text-align: center;
                        page-break-inside: avoid;
                        background: #FAF6F0;
                    }
                    .badge {
                        display: inline-block;
                        background: #143023;
                        color: #D4A359;
                        font-size: 10px;
                        font-weight: 800;
                        padding: 3px 10px;
                        border-radius: 999px;
                        letter-spacing: 0.6px;
                        margin-bottom: 4px;
                    }
                    .cafe-title {
                        font-size: 14px;
                        font-weight: 800;
                        color: #143023;
                        margin-bottom: 6px;
                    }
                    .qr-box {
                        width: 128px;
                        height: 128px;
                        margin: 0 auto 6px auto;
                        padding: 4px;
                        background: #FFFFFF;
                        border: 1.5px solid #D4A359;
                        border-radius: 10px;
                    }
                    .qr-box svg {
                        width: 100%;
                        height: 100%;
                        display: block;
                    }
                    .reward-pill {
                        display: inline-block;
                        background: #D4A359;
                        color: #143023;
                        font-size: 10px;
                        font-weight: 800;
                        padding: 3px 8px;
                        border-radius: 8px;
                        margin-bottom: 5px;
                    }
                    .cta-fr {
                        font-size: 9.5px;
                        font-weight: 600;
                        color: #2B4C3B;
                        margin-bottom: 2px;
                    }
                    .cta-ar {
                        font-size: 10px;
                        font-weight: 700;
                        color: #143023;
                    }
                </style>
            </head>
            <body>
                <div class="grid">
                    $cardsHtml
                </div>
            </body>
            </html>
        """.trimIndent()
    }

    private fun escapeHtml(raw: String): String = raw
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
}
